import {futureIntegrations} from './integrations.mjs';
import {monthSelector,monthView,yearView,months,calendarGrid} from './months.mjs';
import {fixture as f,commitments,money as m,total,analyze,transition,estimatedDate,parseCurrency} from './model.mjs';
import {loadPlan,saveAcceptedPlan,initialPlan,transactions} from './ecosystem-model.mjs';
import {createEcosystem,navigation} from './ecosystem.mjs';
import {createBrand} from './brand.mjs';
import {illustration,logo} from './illustrations.mjs';
let selectedDay=null;let calendarMonth=10;let selectedMonth=10;try{const saved=Number(localStorage.getItem('else-selected-month'));if(saved>=1&&saved<=12)selectedMonth=saved;}catch{}
function account(){try{return JSON.parse(localStorage.getItem('else-mock-session'))||{name:'Aanya',mode:'demo'};}catch{return {name:'Aanya',mode:'demo'};}}
function accountMenu(){const user=account();return `<details class="account-menu"><summary aria-label="Account menu"><span class="avatar" aria-hidden="true">${esc(user.name?.[0]||'A')}</span><span>${esc(user.name||'Aanya')}</span></summary><div class="account-popover"><a href="#/profile">Profile</a><a href="#/history">Monthly history</a><button type="button" data-action="logout">${user.mode==='mock'?'Log out':'Log out / exit demo'}</button></div></details>`;}
function profile(){const user=account();return `${header()}<main id="main" tabindex="-1" class="profile-page fade"><div class="page-heading"><div><div class="eyebrow">Your space</div><h1>A little about you.</h1><p>Make ELSE feel like your place.</p></div></div><div class="profile-layout"><aside class="profile-identity"><span class="avatar profile-avatar" aria-hidden="true">${esc(user.name?.[0]||'A')}</span><h2>${esc(user.name||'Aanya')}</h2><span class="tag">${user.mode==='mock'?'Local account':'Demo explorer'}</span><p>Your plans stay on this device.</p>${illustration('wallet')}</aside><div><form id="profile-form" class="profile-card"><div class="eyebrow">Personal details</div><h2>What should we call you?</h2><label for="profile-name">Display name</label><input id="profile-name" name="displayName" value="${esc(user.name||'Aanya')}" maxlength="40" required><p class="muted">Your name appears in the account menu. Aanya’s sample financial records stay as they are.</p><div class="actions"><button class="btn" type="submit">Save changes <span class="button-arrow" aria-hidden="true">→</span></button><a class="text-btn" href="#/home">Back to your month</a></div></form><section class="profile-session"><div><h2>Your local session</h2><p class="muted">Mock sign-in. No bank connection or saved password.</p></div><button class="btn secondary" type="button" data-action="logout">Log out <span aria-hidden="true">↗</span></button></section></div></div></main>${footer()}`;}
function dateSummary(){const date='2026-'+String(selectedMonth).padStart(2,'0')+'-'+String(selectedDay).padStart(2,'0');const entries=transactions.filter(t=>t.date===date);return `<section class="date-summary"><div><span class="eyebrow">Selected date</span><h2>${selectedDay} ${months[selectedMonth-1]} 2026</h2></div><div>${entries.length?entries.map(t=>`<a href="#/transactions/${t.id}">${esc(t.merchant)} <strong class="num">${m(t.amount)}</strong></a>`).join(''):'<p class="muted">'+(selectedMonth>10||selectedMonth===10&&selectedDay>4?'Upcoming date. No completed activity yet.':'No individual activity is available for this date in the demo.')+'</p>'}<small class="muted">Monthly totals below cover the whole month.</small></div><button class="text-btn" type="button" data-calendar="clear">Clear date</button></section>`;}
function openCalendar(){if(document.querySelector('#calendar-dialog')){document.querySelector('#calendar-dialog').close();return;}calendarMonth=selectedMonth;const dialog=document.createElement('dialog');dialog.id='calendar-dialog';dialog.className='calendar-dialog';dialog.setAttribute('aria-labelledby','calendar-title');dialog.innerHTML=`<button type="button" class="dialog-close" aria-label="Close calendar" data-calendar="close">×</button><h2 id="calendar-title" class="calendar-sr-title">Choose a date or month</h2><div class="calendar-months">${months.map((name,i)=>`<button type="button" data-calendar="month" data-value="${i+1}" aria-pressed="${i+1===calendarMonth}">${name.slice(0,3)}</button>`).join('')}</div><div id="calendar-grid">${calendarGrid(calendarMonth,selectedDay)}</div><div class="calendar-footer"><button class="text-btn" type="button" data-calendar="toggle-months">All months</button><button class="btn" type="button" data-calendar="apply">View month</button></div>`;document.body.append(dialog);dialog.addEventListener('close',()=>{dialog.remove();document.querySelector('.calendar-trigger')?.focus();});dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();dialog.close();return;}if(e.key!=='Tab')return;const controls=[...dialog.querySelectorAll('button:not(:disabled)')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus();}});const trigger=document.querySelector('.calendar-trigger');trigger.setAttribute('aria-expanded','true');dialog.addEventListener('close',()=>trigger.setAttribute('aria-expanded','false'));dialog.show();const rect=trigger.getBoundingClientRect();const width=Math.min(320,innerWidth-32);const height=dialog.getBoundingClientRect().height;dialog.style.left=Math.max(16,Math.min(rect.right-width,innerWidth-width-16))+'px';dialog.style.top=Math.max(16,Math.min(rect.bottom+8,innerHeight-height-16))+'px';dialog.querySelector('[data-calendar=close]').focus();}
function chooseCalendar(day=null){selectedMonth=calendarMonth;selectedDay=day;try{localStorage.setItem('else-selected-month',selectedMonth);}catch{}document.querySelector('#calendar-dialog')?.close();render();document.querySelector('.calendar-trigger')?.focus();}
const app=document.querySelector('#app');let plan;try{plan=loadPlan(localStorage);}catch{plan={...initialPlan};}let draft={amount:12000,item:'New phone',when:'This week'};let setupStep=1;let notice=plan.previous?'Plan updated.':'';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(label,route,cls='btn')=>`<a class="${cls}" href="#/${route}">${label}</a>`;
const button=(label,action,cls='btn')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;
const row=(label,value)=>`<div class="row"><span>${label}</span><strong class="num">${value}</strong></div>`;
const bar=()=>`<div class="bar" role="img" aria-label="Available ₹42,800: committed ₹26,700 and flexible ₹16,100"><span></span><span></span></div><div class="legend"><span><i class="dot"></i>Already committed</span><span><i class="dot light"></i>Flexible before goals</span></div>`;
const protectedList=covered=>`<div class="protected-line"><div class="eyebrow">${covered?'Remains protected':'Protected money stays separate'}</div><div class="protected-list">${(covered?['Rent','Utilities','Internet + mobile','Subscriptions','SIP','Emergency fund']:['Emergency fund — untouched']).map(x=>`<span>✓ ${x}</span>`).join('')}</div></div>`;
function header(landing=false){const route=location.hash.replace('#/','');return `<header class="header"><a class="brand" href="#/${landing?'':'home'}" aria-label="ELSE home">${logo()}</a>${landing?`<nav aria-label="Main navigation"><span class="muted">A little clarity. A little breathing room.</span>${link('Explore demo','home','btn secondary')}</nav>`:navigation(route)+`${accountMenu()}`}</header>`;}
const footer=()=>`${futureIntegrations()}<footer class="footer"><span>ELSE · Know what a purchase changes.</span><span class="creator-credit">A product exploration by <strong>Mitali Giri</strong><small>Local planning only · No bank connection</small></span></footer>`;
function landing(){return brand.landing();}
function home(){return `${header()}<main tabindex="-1" id="main" class="fade"><div class="page-heading"><div><div class="eyebrow">Your October overview</div><h1>A little perspective, ${esc(account().name||'Aanya')}.</h1></div>${monthSelector(selectedMonth)}</div>${notice?`<div class="notice"><div><strong>${notice}</strong><p>${plan.previous?`Your October Goa contribution is now ${m(plan.contribution)}. Planning only; no money moved.`:'Your balance and protected commitments haven’t changed.'}</p></div>${plan.previous?button('Undo','undo','text-btn'):''}</div>`:''}<div class="home-grid"><div><section class="hero-money"><div class="eyebrow">Flexible before goals</div><div class="big num">₹16,100</div><p>After ₹26,700 of upcoming commitments.</p><p class="muted">Planned goal contributions are separate.</p><details><summary>How is this calculated?</summary><p>₹42,800 available − ₹26,700 committed = ₹16,100 flexible. Your Goa plan and preferred buffer have not been deducted.</p></details></section><section class="question">${link('Can I afford something? <span aria-hidden="true">↗</span>','purchase','btn blue')}<p>See what a purchase would change before you decide.</p></section><section class="section"><div class="section-title"><h2>Where your money stands</h2></div>${bar()}${row('Available now','₹42,800')}${row('Already committed','₹26,700')}${row('Flexible before goals','₹16,100')}<div class="row"><span>Preferred month-end buffer<br><small class="muted">A preference, not a commitment</small></span><strong class="num">₹7,000</strong></div><div class="row"><span>Planned Goa contribution<br><small class="muted">Optional allocation from flexible money</small></span><strong class="num">${m(plan.contribution)}</strong></div><p class="muted">After the Goa plan: ${m(16100-plan.contribution)}. After also setting aside your preferred buffer: ${m(16100-plan.contribution-7000)}.</p></section></div><aside class="support"><section class="section"><div class="section-title"><h2>Already spoken for</h2><span class="muted">Coming up</span></div>${commitments.filter(c=>['05','08','12'].includes(c.date)).map(c=>`<div class="commitment"><span class="date">OCT<b>${c.date}</b></span><span>${c.name}</span><strong class="num">${m(c.amount)}</strong></div>`).join('')}<details class="muted" style="margin-top:14px"><summary>All five commitments · ₹26,700</summary>${commitments.map(c=>row(c.name,m(c.amount))).join('')}</details></section><section class="section"><div class="section-title"><h2>A little closer to Goa</h2><span class="muted">Shared goal</span></div>${brand.badge()}<div class="goal-number num">${m(brand.saved())} <small>of ₹30,000</small></div><div class="progress" role="img" aria-label="Goa goal: ${Math.round(brand.saved()/30000*100)} percent saved"><span style="width:${Math.min(100,brand.saved()/30000*100)}%"></span></div><p class="muted">${Math.round(brand.saved()/30000*100)}% saved</p>${row('Planned this month',m(plan.contribution))}${row('Estimated completion',plan.date)}<p class="muted">Illustrative estimate based on your current plan.</p></section><div class="protected-box"><div><strong>Emergency fund</strong><p class="muted">₹96,000 of ₹1,50,000</p></div><span class="tag">✓ Protected</span></div></aside></div>${ecosystem.homeEntries()}</main>${footer()}`;}
function signup(){return brand.auth('signup');}
function login(){return brand.auth('login');}
function setup(){let content=setupStep===1?`<h1>Start with what’s here.</h1><p>Start with the money available for October.</p><label for="income">Monthly take-home income</label><input id="income" value="₹85,000" readonly><label for="balance">Available balance</label><input id="balance" value="₹42,800" readonly><p class="muted" style="margin-top:18px">This concept uses Aanya’s October fixture to keep every scenario consistent.</p>`:setupStep===2?`<h1>Now, what’s already spoken for?</h1><p>Review your remaining commitments.</p>${commitments.map((c,i)=>`<label for="c${i}">${c.name}</label><div class="input-money"><span>₹</span><input id="c${i}" name="c${i}" type="number" min="0" required value="${c.amount}"></div>`).join('')}<div id="commitment-total">${row('Total',m(total))}</div><p class="muted">You can edit these to explore the total. The signature demo uses the original ₹26,700 fixture.</p>`:`<h1>What would you like to protect?</h1><p>Separate essentials from the preferences you can adjust.</p>${row('Emergency fund','₹96,000 · Protected')}${row('Preferred month-end buffer','₹7,000')}<p class="muted">Your buffer is an amount you prefer to keep, not a mandatory bill.</p>${row('Goa · planned this month','₹8,000')}<p class="muted">Goal contributions are optional. Your emergency fund is excluded from purchase scenarios.</p>`;return `${header(true)}<main id="main" class="narrow fade"><form id="setup" class="form-panel"><div class="steps" aria-label="Step ${setupStep} of 3">${[1,2,3].map(n=>`<span class="${n<=setupStep?'active':''}"></span>`).join('')}</div><div class="eyebrow">Step ${setupStep} of 3</div>${illustration(setupStep===1?'wallet':setupStep===2?'receipt':'suitcase')}${content}<div class="actions">${setupStep>1?button('Back','setup-back','btn secondary'):''}<button type="submit" class="btn">${setupStep===3?'See my month →':'Continue →'}</button></div></form></main>${footer()}`;}
function purchase(){plan=transition(plan,'SCENARIO_DRAFT');return `${header()}<main id="main" class="narrow fade">${link('← Back to my month','home','back')}<form id="purchase" class="form-panel"><div class="eyebrow">Explore a purchase</div><h1>What are you thinking about?</h1><p>A what-if for your month. No purchase is made.</p><label for="amount">Amount</label><div class="input-money"><span>₹</span><input id="amount" name="amount" type="text" inputmode="numeric" value="${draft.amount}" required aria-describedby="amount-error"></div><div id="amount-error" class="error"></div><label for="item">What is it?</label><input id="item" name="item" value="${esc(draft.item)}" maxlength="60" required><label for="when">When?</label><select id="when" name="when"><option ${draft.when==='This week'?'selected':''}>This week</option><option ${draft.when==='Later this month'?'selected':''}>Later this month</option></select><div class="actions"><button type="submit" class="btn blue">Check the impact →</button>${link('Cancel','home','text-btn')}</div></form></main>${footer()}`;}
function comparison(s){return `<section class="comparison" aria-label="Before and after the hypothetical purchase"><div class="comparison-head"><span>Monthly picture</span><span>Before</span><span>After purchase</span></div>${[['Available balance',42800,s.available],['Hard commitments',26700,26700],['Flexible before goals',16100,s.after]].map((x,i)=>`<div class="comparison-row ${i===2?'highlight':''}"><span>${x[0]}</span><span class="num">${m(x[1])}</span><span class="num">${m(x[2])}</span></div>`).join('')}</section>`;}
function scenario(){const s=analyze(draft.amount,plan.contribution);return `${header()}<main id="main" class="flow fade">${link('← Your month','home','back')}<div class="flow-header"><p class="purchase-label"><strong class="num">${m(draft.amount)}</strong> · ${esc(draft.item)} · ${esc(draft.when)}</p><h1>Here’s what ${m(draft.amount)}<br>would change.</h1><p>A view of the consequences. The decision stays yours.</p></div><div class="scenario-object">${illustration('phone')}<div>One purchase. A few ripples.<b>${m(s.before)} → ${m(s.after)} flexible</b></div></div>${protectedList(s.covered)}${comparison(s)}<div class="tradeoff"><div><h2>${s.covered?'Your preferred breathing room':'The scenario exceeds flexible money'}</h2><p>${s.gap?`The purchase would leave your flexible money ${m(s.gap)} below the ₹7,000 buffer you prefer to keep.`:'Your flexible remainder meets your preferred ₹7,000 buffer, before planned goal contributions.'}</p><p>Preferred: ₹7,000 · After purchase: ${m(s.after)}</p></div><div><div class="eyebrow">${s.gap?'Buffer gap':'Above preference'}</div><div class="gap num">${s.gap?'−'+m(s.gap):m(s.after-7000)}</div></div></div><section class="option"><div class="eyebrow">Optional plan adjustment</div><h2>One way to ease the goal allocation</h2>${row('October Goa contribution',`${m(plan.contribution)} → ${m(s.proposed)}`)}${row('Estimated completion',`${plan.date} → ${estimatedDate(s.proposed)}`)}<p>Reducing the current ${m(plan.contribution)} Goa plan by ${m(s.released)} releases that amount from your goal allocation.</p><div class="explanation"><strong>Cash and plans are different.</strong> The ${m(s.after)} cash remainder already excludes the purchase and commitments, but does not deduct Goa. Reducing a future contribution cannot increase it to ₹7,000.${s.proposed===5100?' The ₹5,100 option reallocates ₹2,900; the cash buffer gap remains ₹2,900.':''}<br>After this proposed Goa contribution, cash remaining would be ${m(s.after-s.proposed)}. ${s.after-s.proposed<0?'The purchase and goal contribution cannot both be funded from this balance.':''}</div></section><section class="decision"><div class="actions">${button('Adjust my plan','preview','btn secondary')}${button('Keep my current plan','keep','btn secondary')}${link('Try another amount','purchase','btn secondary')}</div><p>Nothing changes until you review and apply. This scenario never executes a payment.</p></section></main>${footer()}`;}
function preview(){const s=analyze(draft.amount,plan.contribution);return `${header()}<main id="main" class="flow fade">${link('← Back to the impact','scenario','back')}<div class="flow-header"><span class="preview-tag">PREVIEW</span><h1>Shift the goal.<br>Keep the decision yours.</h1><p>Your plan hasn’t changed yet.</p></div><div class="preview-summary"><div class="eyebrow">Hypothetical purchase</div>${row(esc(draft.item),m(draft.amount))}<h2 style="margin-top:22px">Current plan → Proposed plan</h2>${row('October Goa contribution',`${m(plan.contribution)} → ${m(s.proposed)}`)}${row('Contribution change',m(s.proposed-plan.contribution))}${row('Estimated completion',`${plan.date} → ${estimatedDate(s.proposed)}`)}${row('Preferred buffer','₹7,000 · unchanged')}${row('Cash after hypothetical purchase',m(s.after))}${row('Cash after purchase + proposed Goa',m(s.after-s.proposed))}${row('Essentials + emergency fund','No change')}</div><p class="preview-footnote">This changes a planned contribution only. It does not restore cash, make a purchase, or transfer money. Completion dates are illustrative estimates.</p><div class="decision"><div class="actions">${button('Apply adjustment','apply','btn blue')}${link('Cancel','scenario','btn secondary')}</div></div></main>${footer()}`;}
const brand=createBrand({getPlan:()=>plan,announce:say,rerender:render,onSession:route=>{setupStep=1;go(route);}});
const ecosystem=createEcosystem({getPlan:()=>plan,getSaved:()=>brand.saved(),brand,useContribution:amount=>{if(amount===plan.contribution){say('No changes made. This contribution is already in your plan.');go('goals/goa');return;}const next=transition({...plan,proposed:amount},'APPLY');if(commitPlan(next)){notice='Plan updated.';go('goals/goa');say('Plan updated. Undo is available.');}}});
function commitPlan(next){try{saveAcceptedPlan(next,localStorage);plan=next;return true;}catch{say("We couldn't save that change. Your previous plan is still intact.");return false;}}
function render(){const route=location.hash==='#main'?'home':location.hash.replace('#/','')||'';const pages={'':landing,home,profile,signup,login,setup,purchase,scenario,preview};const monthly=['home','transactions','insights'].includes(route);const historical=monthly&&selectedMonth!==10;const newScreen=route==='history'?yearView():historical?monthView(selectedMonth,route):ecosystem.screen(route);const product=!['','login','signup','setup','shared/goa'].includes(route);document.body.classList.toggle('is-shared-preview',route==='shared/goa');document.body.classList.toggle('has-product-nav',product);app.innerHTML=`<div class="wrap">${route==='shared/goa'?brand.collaboratorPage(brand.publicSnapshot()):newScreen?header()+newScreen+footer():(pages[route]||landing)()}</div>${product?navigation(route,true):''}`;if(monthly&&selectedDay)document.querySelector('#main .page-heading')?.insertAdjacentHTML('afterend',dateSummary());if(monthly&&!historical&&route!=='home')document.querySelector('#main .page-heading')?.insertAdjacentHTML('beforeend',monthSelector(selectedMonth));if(monthly&&!historical)document.querySelector('#main')?.insertAdjacentHTML('beforeend','<div class="section"><a class="text-btn" href="#/history">Compare all 12 months →</a></div>');brand.afterRender(route);document.title=`ELSE — ${monthly?months[selectedMonth-1]+' 2026 · '+(route==='home'?'Overview':route):({'':'Money decisions, in perspective',home:'Your October',signup:'Create account',login:'Welcome back',setup:'Financial setup',purchase:'Explore a purchase',scenario:'Purchase impact',preview:'Adjustment preview',transactions:'Transactions',goals:'Goals',recurring:'Recurring payments',insights:'Monthly insights'})[route]||route.split('/').map(s=>s.charAt(0).toUpperCase()+s.slice(1)).join(' · ')}`;}
function go(route){if(location.hash===`#/${route}`)render();else location.hash=`/${route}`;}
function say(text){document.querySelector('#status').textContent=text;setTimeout(()=>{document.querySelector('#status').textContent=''},6000);}
window.addEventListener('hashchange',()=>{document.querySelector('#else-dialog')?.close();document.querySelector('#calendar-dialog')?.close();if(location.hash==='#main'){document.querySelector('#main')?.focus();return;}render();window.scrollTo(0,0);const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}});
app.addEventListener('click',e=>{const monthLink=e.target.closest('[data-month]');if(monthLink){selectedDay=null;selectedMonth=Number(monthLink.dataset.month);try{localStorage.setItem('else-selected-month',selectedMonth);}catch{}if(location.hash==='#/home')render();}if(brand.click(e))return;if(ecosystem.click(e))return;const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='logout'){try{localStorage.removeItem('else-mock-session');}catch{}go('login');say('Signed out locally. Saved demo plans remain on this device.');return;}if(action==='preview'){plan={...transition(plan,'ADJUSTMENT_PREVIEW'),proposed:analyze(draft.amount,plan.contribution).proposed};go('preview');}if(action==='apply'){if(commitPlan(transition({...plan,proposed:analyze(draft.amount,plan.contribution).proposed},'APPLY'))){notice='Plan updated.';go('home');say('Plan updated. Undo is available.');}}if(action==='undo'){if(commitPlan(transition(plan,'UNDO'))){notice='Adjustment undone.';render();say('Adjustment undone. Previous Goa plan restored.');}}if(action==='keep'){notice='No changes made.';go('home');say('No changes made. Your current plan is unchanged.');}if(action==='setup-back'){setupStep--;render();}if(action==='login')go('login');});
app.addEventListener('input',e=>{ecosystem.input(e);if(e.target.name?.startsWith('c')&&document.querySelector('#commitment-total')){const sum=[...document.querySelectorAll('#setup input')].reduce((n,i)=>n+Number(i.value),0);document.querySelector('#commitment-total').innerHTML=row('Total',m(sum));}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='profile-form'){const name=new FormData(e.target).get('displayName').trim();if(!name)return;try{localStorage.setItem('else-profile-name',name);localStorage.setItem('else-mock-session',JSON.stringify({...account(),name}));render();say('Profile saved locally.');}catch{say('Could not save profile.');}return;}if(brand.submit(e))return;if(ecosystem.submit(e))return;if(e.target.id==='signup'){setupStep=1;go('setup');}if(e.target.id==='setup'){if(setupStep<3){setupStep++;render();window.scrollTo(0,0);}else go('home');}if(e.target.id==='purchase'){const data=new FormData(e.target);const amount=parseCurrency(data.get('amount'));if(!Number.isInteger(amount)||amount<=0||amount>10000000){document.querySelector('#amount-error').textContent='Enter a whole-rupee amount greater than zero.';return;}draft={amount,item:data.get('item').trim()||'Purchase',when:data.get('when')};plan=transition(plan,'SCENARIO_ANALYZED');go('scenario');}});
render();

document.addEventListener('click',e=>{if(e.target.closest('#else-dialog'))brand.click(e);});
document.addEventListener('submit',e=>{if(e.target.closest('#else-dialog'))brand.submit(e);});

app.addEventListener('change',e=>{if(e.target.id==='month-select'){selectedMonth=Number(e.target.value);try{localStorage.setItem('else-selected-month',selectedMonth);}catch{}render();document.querySelector('#month-select')?.focus();say(months[selectedMonth-1]+' 2026 selected.');}});

document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menu=document.querySelector('.account-menu[open]');if(menu){menu.open=false;menu.querySelector('summary').focus();}}});
document.addEventListener('click',e=>{const menu=document.querySelector('.account-menu[open]');if(menu&&!menu.contains(e.target))menu.open=false;});

document.addEventListener('click',e=>{const target=e.target.closest('[data-calendar]');if(!target)return;const action=target.dataset.calendar;if(action==='open'){openCalendar();return;}if(action==='close'){document.querySelector('#calendar-dialog')?.close();return;}if(action==='toggle-months'){const dialog=document.querySelector('#calendar-dialog');const expanded=dialog.classList.toggle('show-months');target.textContent=expanded?'Back to dates':'All months';return;}if(action==='clear'){selectedDay=null;render();return;}if(action==='apply'){chooseCalendar();return;}if(action==='day'){chooseCalendar(Number(target.dataset.day));return;}if(action==='month'){calendarMonth=Number(target.dataset.value);document.querySelector('#calendar-dialog').classList.remove('show-months');document.querySelector('[data-calendar=toggle-months]').textContent='All months';}if(action==='previous')calendarMonth=Math.max(1,calendarMonth-1);if(action==='next')calendarMonth=Math.min(12,calendarMonth+1);document.querySelector('#calendar-grid').innerHTML=calendarGrid(calendarMonth);document.querySelectorAll('.calendar-months button').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.value)===calendarMonth));if(action==='previous'||action==='next'){const control=document.querySelector('[data-calendar='+action+']');if(control&&!control.disabled)control.focus();else document.querySelector('.calendar-months [aria-pressed=true]')?.focus();}});

document.addEventListener('click',e=>{const calendar=document.querySelector('#calendar-dialog');if(calendar&&!calendar.contains(e.target)&&!e.target.closest('.calendar-trigger'))calendar.close();});window.addEventListener('resize',()=>document.querySelector('#calendar-dialog')?.close());document.addEventListener('scroll',e=>{if(!e.target.closest?.('#calendar-dialog'))document.querySelector('#calendar-dialog')?.close();},true);
